macro_rules! deflateCopy {
    () => {
        # [doc = " Sets the destination stream as a complete copy of the source stream."] # [doc = ""] # [doc = " This function can be useful when several compression strategies will be tried, for example when there are several ways of pre-processing the input data with a filter."] # [doc = " The streams that will be discarded should then be freed by calling [`deflateEnd`]."] # [doc = " Note that [`deflateCopy`] duplicates the internal compression state which can be quite large, so this strategy is slow and can consume lots of memory."] # [doc = ""] # [doc = " # Returns"] # [doc = ""] # [doc = " - [`Z_OK`] if success"] # [doc = " - [`Z_MEM_ERROR`] if there was not enough memory"] # [doc = " - [`Z_STREAM_ERROR`] if the source stream state was inconsistent (such as zalloc being NULL)"] # [doc = ""] # [doc = " The `msg` field is left unchanged in both source and destination."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " The caller must guarantee that"] # [doc = ""] # [doc = " * Either"] # [doc = "     - `dest` is `NULL`"] # [doc = "     - `dest` satisfies the requirements of `&mut *(dest as *mut MaybeUninit<z_stream>)`"] # [doc = " * Either"] # [doc = "     - `source` is `NULL`"] # [doc = "     - `source` satisfies the requirements of `&mut *strm` and was initialized with [`deflateInit_`] or similar"] # [cfg_attr (feature = "export-symbols" , export_name = prefix ! (deflateCopy))] pub unsafe extern "C-unwind" fn deflateCopy (dest : z_streamp , source : z_streamp) -> c_int { let Some (dest) = (unsafe { dest . cast :: < MaybeUninit < DeflateStream > > () . as_mut () }) else { return ReturnCode :: StreamError as _ ; } ; let Some (source) = (unsafe { DeflateStream :: from_stream_mut (source) }) else { return ReturnCode :: StreamError as _ ; } ; zlib_rs :: deflate :: copy (dest , source) as _ }
    };
}

deflateCopy!()